 */
async function handleDebugDirectEvents(req, res) {
  console.warn('[api] WARNING: Using deprecated /debug-direct-events');
  const data = await fetchDebugDirectEvents();

  res.writeHead(200, { 'Content-Type': 'application/json', 'Warning': '299 - "Debug only: Use /supabase-events for production"' });
  res.end(JSON.stringify({
    deprecated: true,
    timestamp: new Date().toISOString(),
    ...data,
    sources: filterCanonicalSources(['ticketmaster', 'kulturhuset', 'malmo-live'])
  }));
}

/**
 * Static test events
 */
async function handleStaticEvents(req, res) {
  res.writeHead(200, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
  res.end(JSON.stringify({
    events: [
      { id: '1', title: 'Test Event 1', date: '2026-03-27', venue: 'Test Venue', source: 'test' },
      { id: '2', title: 'Test Event 2', date: '2026-03-28', venue: 'Test Venue 2', source: 'test' },
    ],
    count: 2
  }));
}

/**
 * Main server router
 */
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);
  console.log(`[${new Date().toISOString()}] ${req.method} ${url.pathname}`);

  if (url.pathname === '/health') {
    await handleHealth(req, res);
  } else if (url.pathname === '/supabase-events') {
    await handleSupabaseEvents(req, res);
  } else if (url.pathname === '/debug-direct-events') {
    await handleDebugDirectEvents(req, res);
  } else if (url.pathname === '/events') {
    // 410 Gone - completely removed
    res.writeHead(410, { 'Content-Type': 'application/json', 'Warning': '299 - "Use /supabase-events for production"' });
    res.end(JSON.stringify({ error: 'Gone: /events is deprecated. Use /supabase-events for production.' }));
  } else if (url.pathname === '/events/static') {
    await handleStaticEvents(req, res);
  } else {
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(`<!DOCTYPE html><html><head><title>EventPulse API</title></head><body>
<h1>EventPulse API Server</h1>
<p>Endpoints:</p>
<ul>
  <li><a href="/health">/health</a> - Health check</li>
  <li><a href="/supabase-events">/supabase-events</a> - <strong>PRIMARY</strong></li>
  <li><a href="/debug-direct-events">/debug-direct-events</a> - <em>Debug only</em></li>
  <li><a href="/events/static">/events/static</a> - Test data</li>
</ul>
</body></html>`);
  }
});

server.listen(PORT, () => {
  console.log(`\n╔════════════════════════════════════════════╗
║     EventPulse API Server                  ║
╠════════════════════════════════════════════╣
║  Server: http://localhost:${PORT}             ║
║  Ticketmaster: ${TICKETMASTER_API_KEY ? 'configured' : 'MISSING'}           ║
║  Supabase: ${supabase ? 'connected' : 'disabled'}                       ║
╚════════════════════════════════════════════╝\n`);
});

